CREATE TABLE IF NOT EXISTS "announcements" (
    "id"          BIGINT    NOT NULL GENERATED BY DEFAULT AS IDENTITY CHECK ("id" >= 0),
    "message"     VARCHAR(500)    NOT NULL,
    "type"        TEXT NOT NULL DEFAULT 'info' CHECK ("type" IN ('info','success','warning','error')),
    "link"        VARCHAR(500)    DEFAULT NULL,
    "linkText"    VARCHAR(100)    DEFAULT NULL,
    "active"      SMALLINT      NOT NULL DEFAULT 1,
    "dismissible" SMALLINT      NOT NULL DEFAULT 0,
    "priority"    SMALLINT  NOT NULL DEFAULT 0 CHECK ("priority" >= 0),
    "startsAt"    TIMESTAMPTZ        DEFAULT NULL,
    "expiresAt"   TIMESTAMPTZ        DEFAULT NULL,
    "createdBy"   BIGINT  DEFAULT NULL CHECK ("createdBy" >= 0),
    "createdAt"   TIMESTAMPTZ        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"   TIMESTAMPTZ        NOT NULL DEFAULT CURRENT_TIMESTAMP ,
    PRIMARY KEY ("id")
);

CREATE OR REPLACE FUNCTION touch_announcements() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW."updatedAt" = CURRENT_TIMESTAMP; RETURN NEW; END $$;

DROP TRIGGER IF EXISTS touch_timestamp ON "announcements";

CREATE TRIGGER touch_timestamp BEFORE UPDATE ON "announcements" FOR EACH ROW EXECUTE FUNCTION touch_announcements();

